"""RiskFlag entity generated by the explainable Digital Twin rule engine."""

from __future__ import annotations

import enum
import uuid
from datetime import datetime, timezone

from sqlalchemy import DateTime, Enum, ForeignKey, String, Text
from sqlalchemy.dialects.postgresql import JSONB, UUID
from sqlalchemy.orm import Mapped, mapped_column, relationship

from app.models.base import Base, UUIDMixin


class RiskSeverity(str, enum.Enum):
    info = "info"
    warning = "warning"
    high = "high"


class RiskFlagStatus(str, enum.Enum):
    open = "open"
    acknowledged = "acknowledged"
    resolved = "resolved"


class RiskFlag(UUIDMixin, Base):
    __tablename__ = "risk_flags"

    recipient_id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True),
        ForeignKey("care_recipients.id", ondelete="CASCADE"),
        nullable=False,
        index=True,
    )
    rule_code: Mapped[str] = mapped_column(String(20), nullable=False)  # R1..R6
    severity: Mapped[RiskSeverity] = mapped_column(
        Enum(RiskSeverity, name="risk_severity_enum", values_callable=lambda x: [e.value for e in x]),
        default=RiskSeverity.info,
        nullable=False,
    )
    message: Mapped[str] = mapped_column(Text, nullable=False)
    evidence: Mapped[dict] = mapped_column(JSONB, default=dict, nullable=False)
    status: Mapped[RiskFlagStatus] = mapped_column(
        Enum(RiskFlagStatus, name="risk_flag_status_enum", values_callable=lambda x: [e.value for e in x]),
        default=RiskFlagStatus.open,
        nullable=False,
        index=True,
    )
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        default=lambda: datetime.now(timezone.utc),
        nullable=False,
    )

    # Relationships
    recipient: Mapped[CareRecipient] = relationship("CareRecipient", back_populates="risk_flags")
